import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { join, resolve } from 'node:path';
import {
	PRISTINE_RELATIVE_PATH,
	UPSTREAM_LOCK_RELATIVE_PATH,
	validateUpstreamLock,
	verifyPristineTree,
} from '../react-port/materialize-lib.mjs';

const MATERIALIZE_CLI = 'scripts/react-port/materialize.mjs';

/**
 * Packages whose upstream evidence is pinned by audit/upstream.lock.json and
 * regenerated by react-port:materialize instead of committed byte-exact.
 */
export function discoverMaterializedUpstreamPackages(root) {
	const packagesRoot = resolve(root, 'packages');
	return readdirSync(packagesRoot, { withFileTypes: true })
		.filter((entry) => entry.isDirectory())
		.map((entry) => `packages/${entry.name}`)
		.filter((packagePath) => existsSync(resolve(root, packagePath, UPSTREAM_LOCK_RELATIVE_PATH)))
		.sort();
}

/**
 * Regenerate the pristine and adapted trees for every lock-pinned package so
 * later verifiers and lanes read complete evidence. The CLI reuses an already
 * verified tree offline; a missing tree costs one archive fetch.
 */
export function materializeUpstreamEvidence(
	root,
	packages = discoverMaterializedUpstreamPackages(root),
) {
	for (const packagePath of packages) {
		const result = spawnSync(
			process.execPath,
			[resolve(root, MATERIALIZE_CLI), 'run', '--package-dir', resolve(root, packagePath)],
			{ cwd: root, encoding: 'utf8' },
		);
		if (result.status !== 0) {
			throw new Error(
				`${packagePath}: materializing pinned upstream evidence failed\n${result.stderr || result.stdout}`,
			);
		}
	}
	return packages;
}

/**
 * Offline integrity check over the committed artifacts of a lock-pinned
 * package: the lock validates against its own fingerprint, every retained
 * upstream license/notice artifact hash-matches the lock's captured evidence,
 * and a materialized pristine tree (when present) matches the lock exactly.
 */
export function verifyMaterializedUpstreamEvidence(root, packagePath) {
	const packageRoot = resolve(root, packagePath);
	const lock = validateUpstreamLock(
		JSON.parse(readFileSync(join(packageRoot, UPSTREAM_LOCK_RELATIVE_PATH), 'utf8')),
	);
	const attribution = join(packageRoot, 'LICENSE.upstream');
	const captured = lock.license.evidence ?? [];
	if (captured.length > 0) {
		if (!existsSync(attribution)) {
			throw new Error(`${packagePath}: LICENSE.upstream attribution artifact is missing`);
		}
		const digest = createHash('sha256').update(readFileSync(attribution)).digest('hex');
		if (!captured.some((entry) => entry.sha256 === digest)) {
			throw new Error(
				`${packagePath}: LICENSE.upstream does not hash-match the lock's captured upstream license`,
			);
		}
	}
	const pristineRoot = join(packageRoot, PRISTINE_RELATIVE_PATH);
	if (existsSync(pristineRoot)) {
		const drift = verifyPristineTree(lock, pristineRoot);
		if (drift.missing.length > 0 || drift.mismatched.length > 0 || drift.unexpected.length > 0) {
			throw new Error(
				`${packagePath}: upstream tree drifted from the lock (missing: ${drift.missing.length}, mismatched: ${drift.mismatched.length}, unexpected: ${drift.unexpected.length})`,
			);
		}
	}
	// A committed pristine tree must also be byte-exact in git's object store:
	// eol/filter attributes can rewrite bytes at add time, which working-tree
	// verification alone cannot see. Tracked blob shas are compared directly to
	// the lock's upstream content addresses.
	const tracked = spawnSync(
		'git',
		['ls-files', '-s', '--', join(packagePath, PRISTINE_RELATIVE_PATH)],
		{
			cwd: root,
			encoding: 'utf8',
		},
	);
	if (tracked.status === 0 && tracked.stdout.trim()) {
		const staged = new Map(
			tracked.stdout
				.trim()
				.split('\n')
				.map((line) => {
					const [meta, file] = line.split('\t');
					return [file, meta.split(' ')[1]];
				}),
		);
		const mangled = lock.files.filter(
			(file) =>
				staged.has(`${packagePath}/${PRISTINE_RELATIVE_PATH}/${file.path}`) &&
				staged.get(`${packagePath}/${PRISTINE_RELATIVE_PATH}/${file.path}`) !== file.gitBlob,
		);
		if (mangled.length > 0) {
			throw new Error(
				`${packagePath}: committed upstream blobs do not match the lock's upstream content addresses (an eol or filter attribute may have rewritten bytes at add time): ${mangled
					.slice(0, 5)
					.map((file) => file.path)
					.join(', ')}`,
			);
		}
	}
	return { lockFingerprint: lock.fingerprint, files: lock.files.length };
}
